{"command": "cd /workspace && python3 - <<'EOF'
import wave, numpy as np
w=wave.open('/workspace/work/t.wav')
d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).astype(float)
def spec(seg,sr=44100):
    F=np.fft.rfft(seg*np.hanning(len(seg)))
    i=np.argmax(abs(F))
    return i*sr/len(seg), abs(F)[i]/len(seg)
for ch in (0,1):
    print('channel',ch)
    for s in [0.05,0.3,0.6,1.0,1.5,2.0,3.0,4.0,5.0]:
        a=int(s*44100); seg=d[a:a+16384,ch]
        if np.sqrt((seg**2).mean())<100: print(f'  t={s} silent'); continue
        f,m=spec(seg)
        print(f'  t={s} peak {f:.1f} Hz mag {m:.0f}')
EOF"}

